<?php require_once __DIR__.'/../config/config.php';role_required(['admin']);$pageTitle='Issues';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare('INSERT INTO issues(volume,issue,issue_title,year,publication_date) VALUES(?,?,?,?,?)');$s->execute([$_POST['volume'],$_POST['issue'],$_POST['issue_title'],$_POST['year'],$_POST['publication_date']?:null]);}$rows=$pdo->query('SELECT * FROM issues ORDER BY year DESC')->fetchAll();include __DIR__.'/../includes/header.php';?><h1 class="title">Issue Management</h1><div class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="grid"><div><label>Volume</label><input name="volume" required></div><div><label>Issue</label><input name="issue" required></div><div><label>Title</label><input name="issue_title"></div><div><label>Year</label><input name="year" value="<?=date('Y')?>" required></div><div><label>Publication Date</label><input type="date" name="publication_date"></div></div><button class="btn primary">Create Issue</button></form></div><div class="panel"><table><tr><th>Volume</th><th>Issue</th><th>Year</th><th>Date</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['volume'])?></td><td><?=e($r['issue'])?></td><td><?=e($r['year'])?></td><td><?=e($r['publication_date'])?></td></tr><?php endforeach;?></table></div><?php include __DIR__.'/../includes/footer.php';?>